-- Up Migration

-- Item catalog: store-specific products customers pick from when building a
-- grocery list. Prices are per `unit` (each, lb or kg). The seed data below is
-- sample data: product names, brands and prices are illustrative, not live.

CREATE TABLE items (
    item_id        INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    store_id       INTEGER NOT NULL,
    name           VARCHAR(150) NOT NULL,
    brand          VARCHAR(100) NOT NULL,
    category       VARCHAR(50) NOT NULL,
    unit           VARCHAR(4) NOT NULL,
    unit_price     NUMERIC(10, 2) NOT NULL,
    dietary_tags   TEXT[] NOT NULL DEFAULT '{}',
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,

    CONSTRAINT fk_items_store
        FOREIGN KEY (store_id) REFERENCES stores(store_id),

    CONSTRAINT uq_items_store_name_brand
        UNIQUE (store_id, name, brand),

    CONSTRAINT chk_items_category
        CHECK (category IN (
            'Produce', 'Dairy & Eggs', 'Meat & Seafood', 'Bakery', 'Pantry',
            'Frozen', 'Beverages', 'Snacks', 'Household'
        )),

    CONSTRAINT chk_items_unit
        CHECK (unit IN ('each', 'lb', 'kg')),

    CONSTRAINT chk_items_unit_price
        CHECK (unit_price > 0.00),

    CONSTRAINT chk_items_dietary_tags
        CHECK (dietary_tags <@ ARRAY[
            'vegan', 'vegetarian', 'gluten-free', 'dairy-free',
            'halal', 'kosher', 'nut-free', 'organic'
        ]::TEXT[])
);

CREATE INDEX idx_items_store_category ON items(store_id, category);
CREATE INDEX idx_items_dietary_tags ON items USING GIN (dietary_tags);

INSERT INTO items (store_id, name, brand, category, unit, unit_price, dietary_tags)
